var i=[{title:`Що робить кожна ділянка`,text:`Грудний відділ хребта: це середня частина спини, і він дає змогу обертатися та розгинатися. Плечовий комплекс включає кульовий суглоб і лопатку, що ковзає по грудній клітці. Досягнення положення над головою залежить від спільної роботи кількох ділянок, тож воно перевіряє більше, ніж гнучкість плечового суглоба.`},{title:`Досліджуйте комфортний рух`,text:`Вправа «відкрита книга» м’яко повертає верх тіла, тоді як стегна лишаються досить нерухомими. Контрольовані кола руками відпрацьовують рух у плечі, а «кіт-корова» проводить хребет через згинання й розгинання у спокійному темпі. Рухайтеся повільно, дихайте нормально і не форсуйте кінцеве положення.`},{title:`Рухливість у ваших підйомах`,text:`Жим над головою може відчуватися плавнішим, коли ребра, лопатки та руки рухаються разом. У тягах дозвольте лопаткам рухатися природно; не потрібно тримати їх притиснутими весь час. Прагніть до плавного контролю в обраній вправі. Немає єдиної жорсткої постави, яку всі мають копіювати.`},{title:`Рухливість плюс сила`,text:`Легкі жими, ковзання по стіні, тяги та контрольовані перенесення розвивають корисну амплітуду та координацію разом. Одна лише розтяжка може покращити пасивну гнучкість, не даючи повного контролю під навантаженням. Якщо вправа відчувається нестабільною чи некомфортною, змініть хват, кут чи амплітуду руху.`},{title:`Як це працює в TrainUp`,text:`Якщо робота над головою турбує ваше плече, додайте плече як обмеження в Профілі з нотаткою. План добирає лише вправи, що відповідають вашим обмеженням. Якщо біль у плечі новий, постійний чи посилюється, зверніться до лікаря чи фізіотерапевта замість того, щоб покладатися на загальні вправи на рухливість.`}];var r=[{label:`ACE 2026: рухливість і гнучкість`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`ACE 2026: практичні поради щодо розтяжки`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`Бібліотека вправ ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var n={sections:i,sources:r};export{n as default,i as sections,r as sources};